css:
.pl { list-style: none; padding: 0; margin: 0; }
.pl li { margin: 0; padding: .3rem 0; break-inside: avoid; max-width: 62ch; }
.pl--one { max-width: 62ch; }
.pl--two { columns: 2 15rem; column-gap: 2.5rem; }
.pl--two li { padding: .18rem 0; }
.pl a { color: var(--os-color-link); text-decoration: underline; text-underline-offset: .18em; text-decoration-thickness: .08em; }
.pl a:hover { text-decoration-thickness: .14em; }
